(function(){
  function score(q, s){
    q=q.toLowerCase(); s=s.toLowerCase();
    var qi=0, sc=0, prev=-2;
    for(var i=0;i<s.length && qi<q.length;i++){
      if(s[i]===q[qi]){
        sc+=1;
        if(i===prev+1) sc+=3;
        var b=(i===0)||s[i-1]===' '||s[i-1]==='-'||s[i-1]==='_'||s[i-1]==='/';
        if(b) sc+=2;
        prev=i; qi++;
      }
    }
    return qi===q.length ? sc : -1;
  }
  function search(q, items){
    items=items||[];
    if(!q) return {value: items.map(function(t){return {text:String(t),score:0};})};
    var out=[];
    for(var i=0;i<items.length;i++){
      var s=items[i]==null?'':String(items[i]);
      var sc=score(q,s);
      if(sc>=0) out.push({text:s,score:sc});
    }
    out.sort(function(a,b){return (b.score-a.score) || (a.text<b.text?-1:1);});
    return {value: out};
  }
  var API={search:search, score:score};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__FzfForge__=API;
})();
